// Validate telemetry message from simulated smart AC room node

const data = msg.payload;

function invalid(reason) {
    msg.validation = {
        valid: false,
        reason: reason,
        checkedAt: new Date().toISOString()
    };
    msg.payload = {
        error: reason,
        originalPayload: data
    };
    return [null, msg];
}

// Check payload exists and is an object
if (!data || typeof data !== "object") {
    return invalid("Payload is missing or not a JSON object");
}

// Required text fields
const requiredTextFields = ["eventId", "buildingId", "roomId", "deviceId", "timestamp"];

for (const field of requiredTextFields) {
    if (!data[field] || typeof data[field] !== "string") {
        return invalid(`Missing or invalid text field: ${field}`);
    }
}

// Required numeric fields
const requiredNumberFields = ["temperatureC", "humidityPct", "occupancy", "co2Ppm", "sequence"];

for (const field of requiredNumberFields) {
    if (typeof data[field] !== "number" || Number.isNaN(data[field])) {
        return invalid(`Missing or invalid numeric field: ${field}`);
    }
}

// Range checks
if (data.temperatureC < 0 || data.temperatureC > 50) {
    return invalid("Temperature is outside expected range 0-50C");
}

if (data.humidityPct < 0 || data.humidityPct > 100) {
    return invalid("Humidity is outside expected range 0-100%");
}

if (data.occupancy < 0 || data.occupancy > 100) {
    return invalid("Occupancy is outside expected range 0-100");
}

if (data.co2Ppm < 300 || data.co2Ppm > 5000) {
    return invalid("CO2 is outside expected range 300-5000 ppm");
}

// Timestamp freshness check
const eventTime = Date.parse(data.timestamp);

if (Number.isNaN(eventTime)) {
    return invalid("Timestamp is not valid ISO date format");
}

const ageMs = Date.now() - eventTime;
const maxAgeMs = 5 * 60 * 1000;

if (ageMs > maxAgeMs) {
    return invalid("Telemetry timestamp is older than 5 minutes");
}

// Add processing metadata
msg.validation = {
    valid: true,
    checkedAt: new Date().toISOString()
};

msg.payload = {
    ...data,
    processing: {
        validatedBy: "node-red",
        validationStatus: "valid",
        validatedAt: new Date().toISOString()
    }
};

// Output 1 = valid, Output 2 = invalid
return [msg, null];

// Classify comfort status before sending data to microservices

const data = msg.payload;

let comfortStatus = "comfortable";
let severity = "normal";
let reasons = [];

if (data.occupancy === 0) {
    comfortStatus = "empty_room";
    severity = "normal";
    reasons.push("Room is empty, energy-saving mode can be used");
}

if (data.temperatureC >= 30) {
    comfortStatus = "too_hot";
    severity = "warning";
    reasons.push("Temperature is high");
}

if (data.temperatureC >= 34) {
    comfortStatus = "critical_hot";
    severity = "critical";
    reasons.push("Temperature is critically high");
}

if (data.humidityPct >= 75) {
    if (severity !== "critical") {
        severity = "warning";
    }
    reasons.push("Humidity is high");
}

if (data.co2Ppm >= 1500) {
    severity = "warning";
    comfortStatus = "poor_air_quality";
    reasons.push("CO2 level is high");
}

if (data.co2Ppm >= 2000) {
    severity = "critical";
    comfortStatus = "critical_air_quality";
    reasons.push("CO2 level is critically high");
}

if (data.occupancy >= 20) {
    if (severity !== "critical") {
        severity = "warning";
    }
    reasons.push("Room occupancy is high");
}

msg.payload = {
    ...data,
    comfortPreCheck: {
        comfortStatus: comfortStatus,
        severity: severity,
        reasons: reasons,
        checkedAt: new Date().toISOString()
    }
};

// Output 1 = normal
// Output 2 = warning/critical
if (severity === "normal") {
    return [msg, null];
}

return [null, msg];
